import React, { useState } from 'react';
import Map, { Marker, Popup, NavigationControl } from 'react-map-gl/maplibre';
import 'maplibre-gl/dist/maplibre-gl.css';
import { Plane, Truck, MapPin, Compass, Layers, RotateCcw } from 'lucide-react';

export default function FleetMap({ telemetryData, vehicleById, theme, selectedVehicle, setSelectedVehicle }) {
  const [viewState, setViewState] = useState({
    longitude: -122.4194,
    latitude: 37.7749,
    zoom: 15,
    pitch: 65,
    bearing: -20
  });

  const mapStyle = {
    version: 8,
    sources: {
      osm: {
        type: 'raster',
        tiles: [
          'https://a.tile.openstreetmap.org/{z}/{x}/{y}.png',
          'https://b.tile.openstreetmap.org/{z}/{x}/{y}.png',
          'https://c.tile.openstreetmap.org/{z}/{x}/{y}.png'
        ],
        tileSize: 256,
        attribution: '&copy; OpenStreetMap Contributors'
      }
    },
    layers: [{ id: 'osm', type: 'raster', source: 'osm', minzoom: 0, maxzoom: 19 }]
  };

  // Reusable inline style for our quick-action preset chips
  const presetButtonStyle = {
    flex: 1, background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.1)',
    borderRadius: '6px', color: '#aaa', fontSize: '11px', padding: '6px 0',
    cursor: 'pointer', textTransform: 'uppercase', fontWeight: '600', transition: 'all 0.2s'
  };

  const handleHover = (e, isHover) => {
    e.currentTarget.style.background = isHover ? 'rgba(255,255,255,0.1)' : 'rgba(255,255,255,0.05)';
    e.currentTarget.style.color = isHover ? '#fff' : '#aaa';
  };

  return (
    <div style={{ width: '100%', height: '100%', position: 'relative' }}>
      <Map
        {...viewState}
        onMove={evt => setViewState(evt.viewState)}
        mapStyle={mapStyle}
        style={{ width: '100%', height: '100%' }}
      >
        <NavigationControl position="top-left" visualizePitch={true} />

        {Object.values(telemetryData).map(pos => {
          const vehicle = vehicleById[pos.vehicle_id];
          if (!vehicle) return null;

          const isGround = vehicle.category === 'GROUND';
          const altitude = isGround ? 0 : (pos.altitude || 50);
          const color = isGround ? 'var(--ground)' : 'var(--accent)';

          return (
            <Marker
              key={pos.vehicle_id}
              longitude={pos.longitude}
              latitude={pos.latitude}
              anchor="bottom"
              onClick={e => { e.originalEvent.stopPropagation(); setSelectedVehicle(vehicle.id); }}
            >
              <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
                <div style={{
                  background: color, color: '#000', borderRadius: '8px', padding: '6px',
                  boxShadow: `0 0 15px ${color}`, transform: `translateY(-${altitude}px)`,
                  transition: 'transform 0.3s ease-out'
                }}>
                  {isGround ? <Truck size={14} /> : <Plane size={14} />}
                </div>

                <div style={{
                  width: '2px', height: `${altitude}px`,
                  background: `linear-gradient(to bottom, ${color}, transparent)`,
                  transition: 'height 0.3s ease-out'
                }} />

                <div style={{
                  width: '12px', height: '4px', background: 'rgba(0,0,0,0.6)',
                  borderRadius: '50%', boxShadow: '0 0 4px rgba(0,0,0,0.8)'
                }} />
              </div>
            </Marker>
          );
        })}

        {selectedVehicle && telemetryData[selectedVehicle] && (
          <Popup
            longitude={telemetryData[selectedVehicle].longitude}
            latitude={telemetryData[selectedVehicle].latitude}
            anchor="top"
            onClose={() => setSelectedVehicle(null)}
            closeButton={false}
          >
            <div className="map-popup">
              <b>{vehicleById[selectedVehicle]?.name}</b>
              <span><MapPin size={11} strokeWidth={2} /> {telemetryData[selectedVehicle].altitude}m</span>
            </div>
          </Popup>
        )}
      </Map>

      {/* STUNNING CAMERA HUD OVERLAY */}
      <div style={{
        position: 'absolute', top: '20px', right: '20px',
        background: 'var(--bg-glass, rgba(18, 18, 22, 0.95))',
        backdropFilter: 'blur(15px)', border: '1px solid rgba(255,255,255,0.08)',
        borderRadius: '16px', padding: '20px', color: '#fff',
        boxShadow: '0 20px 40px rgba(0,0,0,0.5)', zIndex: 10,
        display: 'flex', flexDirection: 'column', gap: '22px', width: '270px'
      }}>

        {/* Pitch Control (3D Perspective Grid) */}
        <div>
          <div style={{ display: 'flex', alignItems: 'center', gap: '14px', marginBottom: '12px' }}>
            <div style={{
              width: '42px', height: '42px', borderRadius: '12px', background: 'rgba(255,255,255,0.05)',
              border: '1px solid rgba(255,255,255,0.1)', display: 'flex', justifyContent: 'center', alignItems: 'center',
              perspective: '100px' // Creates the 3D depth effect
            }}>
              {/* This icon physically tilts in 3D space matching the slider! */}
              <Layers size={22} color="var(--accent, #4f9dff)" style={{
                transform: `rotateX(${viewState.pitch}deg)`,
                transition: 'transform 0.1s'
              }}/>
            </div>
            <div>
              <div style={{ fontSize: '11px', textTransform: 'uppercase', letterSpacing: '1px', color: '#888' }}>Pitch Angle</div>
              <div style={{ fontSize: '16px', fontWeight: '600' }}>{Math.round(viewState.pitch)}°</div>
            </div>
          </div>
          <input
            type="range" min="0" max="85" value={viewState.pitch}
            onChange={e => setViewState(prev => ({ ...prev, pitch: Number(e.target.value) }))}
            style={{ width: '100%', cursor: 'pointer', accentColor: 'var(--accent, #4f9dff)', marginBottom: '8px' }}
          />
          <div style={{ display: 'flex', gap: '8px' }}>
            <button style={presetButtonStyle} onMouseOver={e=>handleHover(e,true)} onMouseOut={e=>handleHover(e,false)} onClick={() => setViewState(prev => ({ ...prev, pitch: 0 }))}>2D Flat</button>
            <button style={presetButtonStyle} onMouseOver={e=>handleHover(e,true)} onMouseOut={e=>handleHover(e,false)} onClick={() => setViewState(prev => ({ ...prev, pitch: 65 }))}>3D View</button>
          </div>
        </div>

        <div style={{ height: '1px', background: 'rgba(255,255,255,0.1)' }} />

        {/* Bearing Control (Rotating Compass) */}
        <div>
          <div style={{ display: 'flex', alignItems: 'center', gap: '14px', marginBottom: '12px' }}>
            <div style={{
              width: '42px', height: '42px', borderRadius: '50%', background: 'rgba(255,255,255,0.05)',
              border: '1px solid rgba(255,255,255,0.1)', display: 'flex', justifyContent: 'center', alignItems: 'center',
            }}>
              {/* This compass dynamically spins to match the map rotation! */}
              <Compass size={22} color="var(--accent, #4f9dff)" style={{
                transform: `rotate(${viewState.bearing}deg)`,
                transition: 'transform 0.1s'
              }}/>
            </div>
            <div>
              <div style={{ fontSize: '11px', textTransform: 'uppercase', letterSpacing: '1px', color: '#888' }}>Bearing</div>
              <div style={{ fontSize: '16px', fontWeight: '600' }}>{Math.round(viewState.bearing)}°</div>
            </div>
          </div>
          <input
            type="range" min="-180" max="180" value={viewState.bearing}
            onChange={e => setViewState(prev => ({ ...prev, bearing: Number(e.target.value) }))}
            style={{ width: '100%', cursor: 'pointer', accentColor: 'var(--accent, #4f9dff)', marginBottom: '8px' }}
          />
          <div style={{ display: 'flex', gap: '8px' }}>
            <button style={presetButtonStyle} onMouseOver={e=>handleHover(e,true)} onMouseOut={e=>handleHover(e,false)} onClick={() => setViewState(prev => ({ ...prev, bearing: 0 }))}>N</button>
            <button style={presetButtonStyle} onMouseOver={e=>handleHover(e,true)} onMouseOut={e=>handleHover(e,false)} onClick={() => setViewState(prev => ({ ...prev, bearing: 90 }))}>E</button>
            <button style={presetButtonStyle} onMouseOver={e=>handleHover(e,true)} onMouseOut={e=>handleHover(e,false)} onClick={() => setViewState(prev => ({ ...prev, bearing: 180 }))}>S</button>
            <button style={presetButtonStyle} onMouseOver={e=>handleHover(e,true)} onMouseOut={e=>handleHover(e,false)} onClick={() => setViewState(prev => ({ ...prev, bearing: -90 }))}>W</button>
          </div>
        </div>

      </div>
    </div>
  );
}
